questionvariables.text:
/* Randomly generate slope of line 1 (not vertical) */
m1:rand_with_prohib(-4,4,[0]); 

/* Randomly generate a point for line 1 */
x0:rand_with_step(-5,5,1);
y0:rand_with_step(-5,5,1);

/* Equation of line 1: y = m1*(x-x0) + y0 */
eq1: y = m1*(x-x0)+y0;

/* Gradient of perpendicular line */
m2: -1/m1;

/* Choose another point on line 2 to define it */
x1:rand_with_prohib(-5,5,[x0]);
y1:m2*(x1-x0)+y0;

/* Equation of line 2: y = m2*(x-x0) + y0 */
eq2: y = m2*(x-x0)+y0;

/* Teacher’s answer: slope of perpendicular line */
ta:m2;
